import React, { useState } from 'react';
import axios from 'axios';
import AdminProducts from './AdminProducts';
import AdminOrders from './AdminOrders';
import AdminDashboard from './AdminDashboard';

function Admin() {
  const [categoryName, setCategoryName] = useState('');
  const [productData, setProductData] = useState({
    name: '',
    price: '',
    unit: '',
    category_id: '',
    image_url: ''
  });
  const [imageFile, setImageFile] = useState(null);
  const [message, setMessage] = useState('');
  const [showProducts, setShowProducts] = useState(false);
  const [showOrders, setShowOrders] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);

  const API_URL = 'http://localhost:3001/api';

  const addCategory = async () => {
    if (!categoryName.trim()) {
      setMessage('❌ Digite o nome da categoria');
      return;
    }
    try {
      await axios.post(`${API_URL}/categories`, { name: categoryName });
      setMessage('✅ Categoria adicionada com sucesso!');
      setCategoryName('');
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage('❌ Erro ao adicionar categoria');
      console.error(error);
    }
  };

  const addProduct = async () => {
    if (!productData.name || !productData.price || !productData.unit || !productData.category_id) {
      setMessage('❌ Preencha todos os campos obrigatórios');
      return;
    }
    try {
      const formData = new FormData();
      formData.append('name', productData.name);
      formData.append('price', parseFloat(productData.price));
      formData.append('unit', productData.unit);
      formData.append('category_id', parseInt(productData.category_id));
      if (imageFile) {
        formData.append('image', imageFile);
      }

      await axios.post(`${API_URL}/products`, formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setMessage('✅ Produto adicionado com sucesso!');
      setProductData({ name: '', price: '', unit: '', category_id: '', image_url: '' });
      setImageFile(null);
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      setMessage('❌ Erro ao adicionar produto');
      console.error(error);
    }
  };

  return (
    <div className="admin">
      <h1>🔧 Painel de Administração</h1>
      
      {message && <div className="admin-message">{message}</div>}

      <div className="admin-tabs">
        <button 
          className={`admin-tab ${!showOrders && !showProducts && !showDashboard ? 'active' : ''}`}
          onClick={() => { setShowOrders(false); setShowProducts(false); setShowDashboard(false); }}
        >
          ➕ Produtos & Categorias
        </button>
        <button 
          className={`admin-tab ${showOrders ? 'active' : ''}`}
          onClick={() => { setShowOrders(true); setShowProducts(false); setShowDashboard(false); }}
        >
          📦 Pedidos
        </button>
        <button 
          className={`admin-tab ${showDashboard ? 'active' : ''}`}
          onClick={() => { setShowDashboard(true); setShowOrders(false); setShowProducts(false); }}
        >
          📊 Dashboard
        </button>
      </div>

      {showDashboard ? (
        <AdminDashboard />
      ) : showOrders ? (
        <AdminOrders />
      ) : (
        <>
          <div className="admin-section">
            <h2>➕ Adicionar Categoria</h2>
            <input
              type="text"
              placeholder="Nome da categoria"
              value={categoryName}
              onChange={(e) => setCategoryName(e.target.value)}
              className="admin-input"
            />
            <button onClick={addCategory} className="admin-btn">Adicionar Categoria</button>
          </div>

          <button onClick={() => setShowProducts(!showProducts)} className="admin-btn" style={{marginTop: '20px'}}>
            {showProducts ? '➖ Fechar Produtos' : '➕ Gerenciar Produtos'}
          </button>

          {showProducts && <AdminProducts />}

          <div className="admin-section">
            <h2>➕ Adicionar Produto</h2>
            <input
              type="text"
              placeholder="Nome do produto"
              value={productData.name}
              onChange={(e) => setProductData({...productData, name: e.target.value})}
              className="admin-input"
            />
            <input
              type="number"
              placeholder="Preço (ex: 10.50)"
              value={productData.price}
              onChange={(e) => setProductData({...productData, price: e.target.value})}
              className="admin-input"
              step="0.01"
            />
            <input
              type="text"
              placeholder="Unidade (ex: kg, L, un)"
              value={productData.unit}
              onChange={(e) => setProductData({...productData, unit: e.target.value})}
              className="admin-input"
            />
            <input
              type="number"
              placeholder="ID da categoria"
              value={productData.category_id}
              onChange={(e) => setProductData({...productData, category_id: e.target.value})}
              className="admin-input"
            />
            <input
              type="file"
              accept="image/*"
              onChange={(e) => setImageFile(e.target.files[0])}
              className="admin-input"
            />

            <button onClick={addProduct} className="admin-btn">Adicionar Produto</button>
          </div>
        </>
      )}
    </div>
  );
}

export default Admin;
